; p3test.asm — generated by p3gen.py: the Pentium III's transcript image (SSE):
; every packed and scalar arithmetic instruction over eight operand pairs
; (zeros, denormals, infinities, quiet and signalling NaNs, the extremes,
; random singles), in register and memory form; ADD/SUB/MUL/DIV/SQRT again
; under each rounding mode and with flush-to-zero; CMPPS/CMPSS on all eight
; predicates; COMISS/UCOMISS; the conversions both ways; the moves,
; shuffles, unpacks and logicals; RCPPS/RSQRTPS (their low 12 significand
; bits masked: the approximation is the part's own); the MMX additions;
; then by hand: FXSAVE/FXRSTOR, LDMXCSR/STMXCSR, the alignment #GP, #XM and
; #UD for an unmasked exception, CR4.OSFXSR, CR0.EM and CR0.TS, SSE2's
; prefixes (#UD). c686test.asm's frame, read from both heads of track 0.
; Run by pgrun.py --mp3 (against Bochs's p3_katmai).
        cpu katmai
        org 0x7C00

STAGE2_LMA  equ 0x7E00
STAGE2_SECS equ 35
IDT_BASE    equ 0x6000
TSS_BASE    equ 0x6800
STACK0      equ 0x7000
STACK3      equ 0x5000
STACK0T     equ 0x6E00
PD          equ 0x10000
PT0         equ 0x11000
PT1         equ 0x12000
SEL_CODE    equ 0x08
SEL_DATA    equ 0x10
SEL_CODE3   equ 0x18 | 3
SEL_DATA3   equ 0x20 | 3
SEL_TSS     equ 0x28
RET_VEC     equ 0x30
TRAP_VEC    equ 0x32                ; a 32-bit trap gate: IF stays as it was
INTR_VEC    equ 0x33                ; a 32-bit interrupt gate: IF cleared
CR4_TSD     equ 0x04
CR4_PSE     equ 0x10
CR4_PGE     equ 0x80
CR4_PCE     equ 0x100

; ---------------------------------------------------------------- stage 1
        bits 16
stage1:
        cli
        cld
        xor ax, ax
        mov ds, ax
        mov es, ax
        mov ss, ax
        mov sp, 0x7C00
        mov ax, 0x0211                  ; 17 sectors: 2-18, head 0
        mov cx, 0x0002
        mov dx, 0x0000
        mov bx, STAGE2_LMA
        int 0x13
        jc  .h
        mov ax, 0x0212                  ; 18: 1-18, head 1
        mov cx, 0x0001
        mov dx, 0x0100
        mov bx, STAGE2_LMA + 17 * 512
        int 0x13
        jc  .h
        jmp stage2
.h:     hlt
        jmp .h
        times 510 - ($ - $$) db 0
        dw 0xAA55

; ---------------------------------------------------------------- stage 2
stage2:
        mov eax, cr0                ; ET as the machine came up
        mov [cr0_boot], eax
        mov al, 0xFF                ; every IRQ masked at the PIC: ring 3 runs with IF
        out 0x21, al                ; set, and a timer tick there reads as vector 8 (a
        out 0xA1, al                ; slow -V run on the host clock took one in T23)
        in al, 0x92                 ; A20 on
        or al, 2
        out 0x92, al
        lgdt [gdtr]
        mov eax, cr0
        or al, 1
        mov cr0, eax
        jmp SEL_CODE:pm32

        bits 32
pm32:
        mov ax, SEL_DATA
        mov ds, ax
        mov es, ax
        mov fs, ax
        mov gs, ax
        mov ss, ax
        mov esp, STACK0
        mov edi, IDT_BASE
        xor ecx, ecx
.idt:   mov eax, fault_stubs
        mov edx, ecx
        shl edx, 3
        add eax, edx
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8E00
        shr eax, 16
        mov [edi+6], ax
        add edi, 8
        inc ecx
        cmp ecx, 32
        jb .idt
        mov edi, IDT_BASE + RET_VEC * 8
        mov eax, ret_trap
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0xEE00
        shr eax, 16
        mov [edi+6], ax
        mov edi, IDT_BASE + TRAP_VEC * 8
        mov eax, if_probe
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8F00
        shr eax, 16
        mov [edi+6], ax
        mov edi, IDT_BASE + INTR_VEC * 8
        mov eax, if_probe
        mov [edi], ax
        mov word [edi+2], SEL_CODE
        mov word [edi+4], 0x8E00
        shr eax, 16
        mov [edi+6], ax
        lidt [idtr]
        mov dword [TSS_BASE + 4], STACK0T
        mov dword [TSS_BASE + 8], SEL_DATA
        mov word [TSS_BASE + 0x66], 0x68
        mov ax, SEL_TSS
        ltr ax
        mov dword [0x30000], 0x11223344
        mov dword [0x30004], 0x55667788
        mov dword [0x30020], 5
        mov dword [0x32000], 0x99AABBCC
        mov dword [0x34010], 0xDEADBEEF
        mov dword [0x36010], 0xFEEDFACE
        mov dword [0x30FFC], 0xAAAAAAAA     ; a CMPXCHG8B across into a read-only page
        mov dword [0x31000], 0xBBBBBBBB
        mov dword [0x400000], 0             ; (as a page table, with PSE off: nothing present)
        mov dword [0x400010], 0xCAFEBABE    ; in the 4 MB page at 400000
        mov dword [0x5FF000], 0x13579BDF
        mov edi, PD
        mov ecx, 1024
        xor eax, eax
        rep stosd
        mov dword [PD + 0], PT0 | 7
        mov dword [PD + 4], PT1 | 7
        mov edi, PT0
        mov eax, 7
        mov ecx, 1024
.pt0:   stosd
        add eax, 0x1000
        loop .pt0
        mov dword [PT0 + 0x32 * 4], 0x32000 | 5    ; user, read-only
        mov dword [PT0 + 0x31 * 4], 0x31000 | 5    ; user, read-only
        mov dword [PD + 8], 0x400000 | 0x87        ; linear 800000: a 4 MB page, user r/w (PS)
        mov dword [PD + 12], 0x400000 | 0x83       ; linear C00000: the same, supervisor
        mov edi, PT1
        mov ecx, 1024
        xor eax, eax
        rep stosd
        mov dword [PT1 + 0], 0x34000 | 7           ; linear 400000 -> 34000
        mov eax, PD
        mov cr3, eax
        mov eax, cr0
        or eax, 0x80000000
        mov cr0, eax
        jmp .paged
.paged:
        mov esi, msg_start
        call puts

        ; ---- CPUID
        mov byte [tno], 1
        mov eax, 1
        cpuid
        call ok_eax
        mov byte [tno], 2
        mov eax, 1
        cpuid
        mov eax, edx
        call ok_eax
        mov byte [tno], 3
        mov eax, 2
        cpuid
        mov eax, edx
        call ok_eax

        ; ---- SSE on: CR4.OSFXSR and OSXMMEXCPT
        mov eax, cr4
        or eax, 0x600
        mov cr4, eax
        mov byte [tno], 4
        stmxcsr [tmpi]
        mov eax, [tmpi]                     ; 1F80 at reset
        call ok_eax
        mov dword [qno], 0

        ; ---- each stub over each pair: X<n> xmm0 (lanes 3..0) and MXCSR
        mov dword [cur_mx], 0x1F80
        mov esi, main_stubs
        call run_table
        mov esi, rc_stubs                   ; the rounding modes, and FTZ
        mov dword [cur_mx], 0x3F80
        call run_table
        mov dword [cur_mx], 0x5F80
        call run_table
        mov dword [cur_mx], 0x7F80
        call run_table
        mov dword [cur_mx], 0x9F80
        call run_table
        mov dword [cur_mx], 0x1F80
        mov esi, mmx_stubs                  ; the MMX additions: Q<n> mm0
        call run_mmx
        emms

        ; ---- unmasked exceptions: #XM (OSXMMEXCPT), #UD without it; the destination kept
        mov byte [tno], 0x40
        mov dword [resume], .t41
        movaps xmm0, [pairs]
        xorps xmm1, xmm1
        mov dword [tmpi], 0x1D80            ; ZE unmasked
        ldmxcsr [tmpi]
        divps xmm0, xmm1
        call ok_eax
.t41:   mov byte [tno], 0x41
        stmxcsr [tmpi]
        mov eax, [tmpi]                     ; ZE set
        call ok_eax
        mov byte [tno], 0x42
        movss [tmpi], xmm0
        mov eax, [tmpi]                     ; xmm0 as it was
        call ok_eax
        mov byte [tno], 0x43
        mov dword [resume], .t44
        mov eax, cr4
        and eax, ~0x400
        mov cr4, eax
        divps xmm0, xmm1                    ; #UD
        call ok_eax
.t44:   mov eax, cr4
        or eax, 0x400
        mov cr4, eax
        mov dword [tmpi], 0x1F80
        ldmxcsr [tmpi]
        mov byte [tno], 0x44
        mov dword [resume], .t45
        mov dword [tmpi], 0x10000           ; a reserved bit: #GP
        ldmxcsr [tmpi]
        call ok_eax
.t45:   mov byte [tno], 0x45
        mov dword [resume], .t46
        mov dword [tmpi], 0xFFBF            ; every writable bit
        ldmxcsr [tmpi]
        stmxcsr [tmpi]
        mov eax, [tmpi]
        call ok_eax
.t46:   mov dword [tmpi], 0x1F80
        ldmxcsr [tmpi]

        ; ---- alignment, CR4.OSFXSR, CR0.EM, CR0.TS, SSE2's prefixes
        mov byte [tno], 0x50
        mov dword [resume], .t51
        movaps xmm0, [pairs + 4]            ; #GP
        call ok_eax
.t51:   mov byte [tno], 0x51
        mov dword [resume], .t52
        addps xmm0, [pairs + 4]             ; #GP
        call ok_eax
.t52:   mov byte [tno], 0x52
        mov dword [resume], .t53
        addss xmm0, [pairs + 4]             ; scalar: fine
        call ok_eax
.t53:   mov byte [tno], 0x53
        mov dword [resume], .t54
        mov eax, cr4
        and eax, ~0x200
        mov cr4, eax
        addps xmm0, xmm1                    ; OSFXSR clear: #UD
        call ok_eax
.t54:   mov byte [tno], 0x54
        mov dword [resume], .t55
        stmxcsr [tmpi]                      ; #UD too
        call ok_eax
.t55:   mov eax, cr4
        or eax, 0x200
        mov cr4, eax
        mov byte [tno], 0x55
        mov dword [resume], .t56
        mov eax, cr0
        or eax, 4
        mov cr0, eax
        addps xmm0, xmm1                    ; EM: #UD
        call ok_eax
.t56:   mov eax, cr0
        and eax, ~4
        mov cr0, eax
        mov byte [tno], 0x56
        mov dword [resume], .t57
        mov eax, cr0
        or eax, 8
        mov cr0, eax
        addps xmm0, xmm1                    ; TS: #NM
        call ok_eax
.t57:   clts
        mov byte [tno], 0x57
        mov dword [resume], .t58
        db 0x66, 0x0F, 0x58, 0xC1           ; addpd: #UD on a Pentium III
        call ok_eax
.t58:   mov byte [tno], 0x58
        mov dword [resume], .t59
        db 0xF2, 0x0F, 0x58, 0xC1           ; addsd
        call ok_eax
.t59:   mov byte [tno], 0x59
        mov dword [resume], .t5a
        sfence
        mov eax, 1
        call ok_eax
.t5a:   mov byte [tno], 0x5A
        mov dword [resume], .t60
        prefetchnta [pairs]
        prefetcht0 [0x1000000]              ; not present: no fault
        mov eax, 2
        call ok_eax

        ; ---- FXSAVE / FXRSTOR: the image over a filled area, then back
.t60:   mov edi, fxarea
        mov ecx, 512 / 4
        mov eax, 0xA5A5A5A5
        rep stosd
        finit
        fld1
        fldpi                               ; two registers, TOP 6
        movaps xmm3, [pairs + 32]
        mov dword [tmpi], 0x3F81            ; RC down, IE set
        ldmxcsr [tmpi]
        fxsave [fxarea]
        mov esi, fxarea
        mov ecx, 0
.fx:    mov byte [tno], 0x70
        mov eax, [esi]
        call ok_eax
        add esi, 4
        inc ecx
        cmp ecx, 300 / 4
        jb .fx
        mov byte [tno], 0x71
        finit
        xorps xmm3, xmm3
        mov dword [tmpi], 0x1F80
        ldmxcsr [tmpi]
        fxrstor [fxarea]
        stmxcsr [tmpi]
        mov eax, [tmpi]                     ; 3F81 again
        call ok_eax
        mov byte [tno], 0x72
        movss [tmpi], xmm3
        mov eax, [tmpi]
        call ok_eax
        mov byte [tno], 0x73
        fnstsw ax
        call ok_eax
        mov byte [tno], 0x74
        fstp dword [tmpi]                   ; pi
        mov eax, [tmpi]
        call ok_eax
        mov byte [tno], 0x75
        mov dword [resume], .t76
        fxsave [fxarea + 8]                 ; misaligned: #GP
        call ok_eax
.t76:   mov byte [tno], 0x76
        mov dword [resume], .t77
        mov dword [fxarea + 24], 0x10000    ; a reserved MXCSR bit: #GP
        fxrstor [fxarea]
        call ok_eax
.t77:   mov byte [tno], 0x77                ; OSFXSR clear: the SSE part not saved
        mov dword [resume], t60_done
        mov edi, fxarea
        mov ecx, 512 / 4
        mov eax, 0xA5A5A5A5
        rep stosd
        mov eax, cr4
        and eax, ~0x200
        mov cr4, eax
        fxsave [fxarea]
        mov eax, cr4
        or eax, 0x200
        mov cr4, eax
        mov eax, [fxarea + 24]
        call ok_eax
        mov byte [tno], 0x78
        mov eax, [fxarea + 160]
        call ok_eax
        mov byte [tno], 0x79
        mov eax, [fxarea + 32]
        call ok_eax
        finit
        jmp t60_done

run_table:                                  ; ESI: stubs; each over each pair
.op:    mov ebx, [esi]
        test ebx, ebx
        jz .d
        mov edi, pairs
        mov ecx, NPAIRS
.pair:  movaps xmm0, [edi]
        movaps xmm1, [edi + 16]
        ldmxcsr [cur_mx]
        push edi
        push ecx
        call ebx
        pop ecx
        pop edi
        call pr_x0
        add edi, 32
        loop .pair
        add esi, 4
        jmp .op
.d:     ret
run_mmx:
.op:    mov ebx, [esi]
        test ebx, ebx
        jz .d
        mov edi, pairs
        mov ecx, NPAIRS
.pair:  movq mm0, [edi]
        movq mm1, [edi + 16]
        push edi
        push ecx
        call ebx
        pop ecx
        pop edi
        call pr_mm0
        add edi, 32
        loop .pair
        add esi, 4
        jmp .op
.d:     ret
t60_done:
.t60:   xor eax, eax
        mov cr4, eax
        mov esi, msg_done
        call puts
        mov al, 0
        out 0xF4, al
.h:     hlt
        jmp .h
ring3:
        mov [saved_esp], esp
        mov dword [resume], .back
        mov ax, SEL_DATA3
        mov ds, ax
        mov es, ax
        push dword SEL_DATA3
        push dword STACK3
        push dword [r3flags]
        push dword SEL_CODE3
        push ebx
        iretd
.back:  ret

pr_x0:                                      ; "X<n> " lanes 3..0, MXCSR; then MXCSR back to cur_mx
        pushad
        movups [tmpx], xmm0
        stmxcsr [tmpm]
        mov esi, msg_x
        call puts
        mov eax, [qno]
        call hex16
        mov ebx, 12
.l:     mov al, ' '
        out 0xE9, al
        mov eax, [tmpx + ebx]
        call hex32
        sub ebx, 4
        jns .l
        mov al, ' '
        out 0xE9, al
        mov eax, [tmpm]
        call hex32
        mov al, 10
        out 0xE9, al
        ldmxcsr [cur_mx]
        inc dword [qno]
        popad
        ret
pr_mm0:
        pushad
        movq [tmpq], mm0
        mov esi, msg_q
        call puts
        mov eax, [qno]
        call hex16
        mov al, ' '
        out 0xE9, al
        mov eax, [tmpq + 4]
        call hex32
        mov eax, [tmpq]
        call hex32
        mov al, 10
        out 0xE9, al
        inc dword [qno]
        popad
        ret
x1:
        sqrtps xmm0, xmm1
        ret
x2:
        sqrtps xmm0, [edi + 16]
        ret
x3:
        sqrtss xmm0, xmm1
        ret
x4:
        sqrtss xmm0, [edi + 16]
        ret
x5:
        addps xmm0, xmm1
        ret
x6:
        addps xmm0, [edi + 16]
        ret
x7:
        addss xmm0, xmm1
        ret
x8:
        addss xmm0, [edi + 16]
        ret
x9:
        mulps xmm0, xmm1
        ret
x10:
        mulps xmm0, [edi + 16]
        ret
x11:
        mulss xmm0, xmm1
        ret
x12:
        mulss xmm0, [edi + 16]
        ret
x13:
        subps xmm0, xmm1
        ret
x14:
        subps xmm0, [edi + 16]
        ret
x15:
        subss xmm0, xmm1
        ret
x16:
        subss xmm0, [edi + 16]
        ret
x17:
        minps xmm0, xmm1
        ret
x18:
        minps xmm0, [edi + 16]
        ret
x19:
        minss xmm0, xmm1
        ret
x20:
        minss xmm0, [edi + 16]
        ret
x21:
        divps xmm0, xmm1
        ret
x22:
        divps xmm0, [edi + 16]
        ret
x23:
        divss xmm0, xmm1
        ret
x24:
        divss xmm0, [edi + 16]
        ret
x25:
        maxps xmm0, xmm1
        ret
x26:
        maxps xmm0, [edi + 16]
        ret
x27:
        maxss xmm0, xmm1
        ret
x28:
        maxss xmm0, [edi + 16]
        ret
x29:
        rcpps xmm0, xmm1
        andps xmm0, [m_approx]
        ret
x30:
        rcpss xmm0, xmm1
        andps xmm0, [m_approx]
        ret
x31:
        rsqrtps xmm0, xmm1
        andps xmm0, [m_approx]
        ret
x32:
        rsqrtss xmm0, xmm1
        andps xmm0, [m_approx]
        ret
x33:
        andps xmm0, xmm1
        ret
x34:
        andps xmm0, [edi + 16]
        ret
x35:
        andnps xmm0, xmm1
        ret
x36:
        andnps xmm0, [edi + 16]
        ret
x37:
        orps xmm0, xmm1
        ret
x38:
        orps xmm0, [edi + 16]
        ret
x39:
        xorps xmm0, xmm1
        ret
x40:
        xorps xmm0, [edi + 16]
        ret
x41:
        unpcklps xmm0, xmm1
        ret
x42:
        unpcklps xmm0, [edi + 16]
        ret
x43:
        unpckhps xmm0, xmm1
        ret
x44:
        unpckhps xmm0, [edi + 16]
        ret
x45:
        shufps xmm0, xmm1, 0x1B
        ret
x46:
        shufps xmm0, xmm1, 0xE4
        ret
x47:
        shufps xmm0, xmm1, 0x4E
        ret
x48:
        shufps xmm0, xmm1, 0xB1
        ret
x49:
        cmpps xmm0, xmm1, 0
        ret
x50:
        cmpss xmm0, [edi + 16], 0
        ret
x51:
        cmpps xmm0, xmm1, 1
        ret
x52:
