        ret
x65:
        mov dword [tmpi], 0x8D7
        push dword [tmpi]
        popfd
        comiss xmm0, xmm1
        pushfd
        pop eax
        and eax, 0x8D5
        mov [tmpi], eax
        movss xmm0, [tmpi]
        ret
x66:
        mov dword [tmpi], 0x8D7
        push dword [tmpi]
        popfd
        ucomiss xmm0, xmm1
        pushfd
        pop eax
        and eax, 0x8D5
        mov [tmpi], eax
        movss xmm0, [tmpi]
        ret
x67:
        movaps xmm0, [edi + 16]
        ret
x68:
