; fault: report vector, error code (if any) and CR2, resume the script
fault:
        mov bx, SEL_DATA
        mov ds, bx
        mov es, bx
        pop ecx
        mov esi, msg_t
        call puts
        movzx eax, byte [tno]
        call hex8
        mov esi, msg_v
        call puts
        mov eax, ecx
        call hex8
        cmp ecx, 8
        je .err
        cmp ecx, 17
        je .err
        cmp ecx, 10
        jb .noerr
        cmp ecx, 14
        ja .noerr
.err:   mov esi, msg_e
        call puts
        pop eax
        call hex16
.noerr: mov esi, msg_cr2
        call puts
        mov eax, cr2
        call hex32
        mov al, 10
        out 0xE9, al
        mov esp, [saved_esp]
        cmp dword [saved_esp], 0
        jne .go
        mov esp, STACK0
.go:    jmp [resume]

ok_eax:
        push eax
        mov esi, msg_t
        call puts
        movzx eax, byte [tno]
        call hex8
        mov esi, msg_ok
        call puts
        pop eax
        call hex32
        mov al, 10
        out 0xE9, al
        ret

puts:   lodsb
        test al, al
        jz .d
        out 0xE9, al
        jmp puts
.d:     ret
hex32:  push eax
        shr eax, 16
        call hex16
        pop eax
hex16:  push eax
        shr eax, 8
        call hex8
        pop eax
hex8:   push eax
        shr al, 4
        call .n
        pop eax
.n:     and al, 15
        add al, '0'
        cmp al, '9'
        jbe .p
        add al, 7
.p:     out 0xE9, al
        ret

