msg_v     db " v=", 0
msg_e     db " e=", 0
msg_cr2   db " cr2=", 0
tno       db 0
          align 4
resume    dd 0
saved_esp dd 0
cr0_boot  dd 0
r3flags   dd 0x202
flg       dd 0
qno       dd 0
tmpi      dd 0
tmpm      dd 0
cur_mx    dd 0x1F80
          align 8
tmpq      dq 0
msg_x     db "X", 0
msg_q     db "Q", 0
tmp       dd 0
f_two     dd 2.0
cw_ie     dw 0x037E                       ; IE unmasked
t_one     dt 1.0
t_two     dt 2.0
t_qnan    dq 0xC000000000000000
          dw 0x7FFF
t_snan    dq 0xA000000000000000
          dw 0x7FFF

gdt:    dq 0
        dq 0x00CF9A000000FFFF       ; 08 code, ring 0
        dq 0x00CF92000000FFFF       ; 10 data, ring 0
        dq 0x00CFFA000000FFFF       ; 18 code, ring 3
        dq 0x00CFF2000000FFFF       ; 20 data, ring 3
        dw 0x67, TSS_BASE, 0x8900, 0 ; 28 386 TSS
gdt_end:
gdtr:   dw gdt_end - gdt - 1
        dd gdt
idtr:   dw 0x34 * 8 - 1
        dd IDT_BASE

        times (STAGE2_SECS + 1) * 512 - ($ - $$) db 0
